import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import CityHeader from "@/components/city-header";
import CityGrid from "@/components/city-grid";
import ControlPanel from "@/components/control-panel";
import BuildingModal from "@/components/building-modal";
import { useCitySimulation } from "@/hooks/use-city-simulation";
import type { Tool, BuildingType } from "@shared/schema";

export default function CitySimulation() {
  const [selectedTool, setSelectedTool] = useState<Tool>("residential");
  const [selectedBuilding, setSelectedBuilding] = useState<BuildingType | null>(null);
  const [showBuildingModal, setShowBuildingModal] = useState(false);

  const { data: city, isLoading } = useQuery({
    queryKey: ["/api/cities", "default-city"],
  });

  const { 
    updateCityCell, 
    saveCity, 
    pauseTime, 
    setTimeSpeed,
    placeBuilding,
    isUpdating 
  } = useCitySimulation("default-city");

  const handleCellClick = (row: number, col: number) => {
    if (selectedTool === "bulldozer") {
      updateCityCell(row, col, { zoneType: "empty", buildingType: undefined });
    } else if (selectedTool === "park") {
      updateCityCell(row, col, { zoneType: "park", level: 1 });
    } else if (selectedTool !== "infrastructure") {
      updateCityCell(row, col, { zoneType: selectedTool });
    }
  };

  const handleBuildingPlace = (buildingType: BuildingType) => {
    setSelectedBuilding(buildingType);
    setSelectedTool("infrastructure");
    setShowBuildingModal(true);
  };

  const handleConfirmBuilding = (row: number, col: number) => {
    if (selectedBuilding) {
      placeBuilding(row, col, selectedBuilding);
      setShowBuildingModal(false);
      setSelectedBuilding(null);
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center" data-testid="loading-spinner">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (!city) {
    return (
      <div className="min-h-screen flex items-center justify-center" data-testid="city-not-found">
        <div className="text-center">
          <h2 className="text-2xl font-bold text-destructive">City not found</h2>
          <p className="text-muted-foreground">Unable to load city data</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-background" data-testid="city-simulation">
      <CityHeader
        city={city}
        onSave={saveCity}
        onPause={pauseTime}
        onTimeSpeedChange={setTimeSpeed}
        data-testid="city-header"
      />

      <div className="flex-1 flex">
        <main className="flex-1 p-6" data-testid="main-content">
          <CityGrid
            city={city}
            selectedTool={selectedTool}
            selectedBuilding={selectedBuilding}
            onCellClick={handleCellClick}
            onBuildingClick={handleConfirmBuilding}
            data-testid="city-grid"
          />
        </main>

        <ControlPanel
          city={city}
          selectedTool={selectedTool}
          onToolSelect={setSelectedTool}
          onBuildingSelect={handleBuildingPlace}
          data-testid="control-panel"
        />
      </div>

      <BuildingModal
        building={selectedBuilding}
        isOpen={showBuildingModal}
        onClose={() => setShowBuildingModal(false)}
        onConfirm={() => setShowBuildingModal(false)}
        data-testid="building-modal"
      />
    </div>
  );
}

